#!/usr/bin/env python3
"""Generate python/THIRD_PARTY_NOTICES.txt for the Python wheel.

The wheel statically links the Rust packages in the *normal* (non-dev, non-build)
dependency graph of python/Cargo.toml. This script takes the union of that graph
over the three platforms CI builds for, reads each package's licence expression
from `cargo metadata`, and copies the licence and notice files shipped inside the
package source (from the local cargo registry) into one file.

    python .github/scripts/gen_notices.py          # write the file
    python .github/scripts/gen_notices.py --check  # fail if it is out of date

Nothing is downloaded: run `cargo fetch --manifest-path python/Cargo.toml` first
if the sources are not in the local registry. Packages without any licence file
in their source are listed in the output header and make the script exit 1, so a
missing notice cannot go unnoticed.
"""
import json
import pathlib
import re
import subprocess
import sys

ROOT = pathlib.Path(__file__).resolve().parents[2]
MANIFEST = ROOT / "python" / "Cargo.toml"
OUT = ROOT / "python" / "THIRD_PARTY_NOTICES.txt"
TARGETS = ["x86_64-pc-windows-msvc", "x86_64-unknown-linux-gnu", "aarch64-apple-darwin"]
OWN = {"quantkit", "quantkit-py"}
NAME_RE = re.compile(r"^(LICEN[CS]E|COPYING|NOTICE|UNLICENSE|COPYRIGHT)", re.I)


def run(*args):
    return subprocess.run(args, check=True, capture_output=True, text=True).stdout


def linked_packages():
    ids = set()
    for target in TARGETS:
        out = run("cargo", "tree", "--manifest-path", str(MANIFEST), "-e", "normal",
                  "--target", target, "--prefix", "none", "--format", "{p}", "--locked")
        for line in out.splitlines():
            m = re.match(r"^(\S+) v(\S+)", line.strip())
            if m:
                ids.add((m.group(1), m.group(2)))
    return sorted(ids - {(n, v) for n, v in ids if n in OWN})


def main():
    meta = json.loads(run("cargo", "metadata", "--format-version", "1", "--locked",
                          "--manifest-path", str(MANIFEST)))
    by_key = {(p["name"], p["version"]): p for p in meta["packages"]}
    parts, missing = [], []
    pkgs = linked_packages()
    for key in pkgs:
        pkg = by_key[key]
        src = pathlib.Path(pkg["manifest_path"]).parent
        files = sorted(f for f in src.iterdir() if f.is_file() and NAME_RE.match(f.name))
        header = f'{key[0]} {key[1]}\nlicence expression: {pkg.get("license") or "(none declared)"}\n'
        if pkg.get("repository"):
            header += f'source: {pkg["repository"]}\n'
        body = ""
        for f in files:
            text = f.read_bytes().decode("utf-8", errors="replace").replace("\r\n", "\n").strip()
            body += f"\n--- {f.name} ---\n{text}\n"
        if not files:
            missing.append(key)
            body = "\n(no licence file found in the package source)\n"
        parts.append("=" * 78 + "\n" + header + body)
    intro = (
        "THIRD-PARTY NOTICES for the quantkit-rs wheel\n\n"
        "The compiled extension statically links the Rust packages listed below.\n"
        "Each is distributed under the licence expression shown; where an expression\n"
        "offers a choice (OR), the quantkit-rs wheel is distributed under the\n"
        "permissive alternative. The licence and notice files are reproduced from each\n"
        "package's source. Generated by .github/scripts/gen_notices.py from\n"
        "python/Cargo.lock (normal dependencies for Windows, Linux and macOS targets).\n"
        f"Packages listed: {len(pkgs)}.\n"
    )
    if missing:
        intro += "WARNING, packages without a licence file in their source: " + ", ".join(
            f"{n} {v}" for n, v in missing) + "\n"
    text = intro + "\n" + "\n".join(parts)
    if "--check" in sys.argv:
        current = OUT.read_text(encoding="utf-8") if OUT.exists() else ""
        if current != text:
            print("python/THIRD_PARTY_NOTICES.txt is out of date; rerun gen_notices.py")
            return 1
        print(f"notices up to date ({len(pkgs)} packages)")
    else:
        OUT.write_text(text, encoding="utf-8", newline="\n")
        print(f"wrote {OUT} ({len(pkgs)} packages)")
    if missing:
        print("packages without licence files:", missing)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
